arguments.file_text:
@using System.Globalization

<div class="message-item @(IsHighlighted ? "highlighted" : "")"
     @onmouseenter="() => _hovered = true"
     @onmouseleave="OnMouseLeave">

    <div class="message-header">
        <span class="author">@Message.Author</span>
        <span class="timestamp" title="@Message.SentAt.ToString("f", CultureInfo.InvariantCulture)">@FormatRelativeTime(Message.SentAt)</span>
    </div>

    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ThreadSummary is not null)
    {
        <button class="thread-link" @onclick="OpenThread">
            💬 @ThreadSummary.ReplyCount @(ThreadSummary.ReplyCount == 1 ? "reply" : "replies")
            <span class="thread-time">Last reply @FormatRelativeTime(ThreadSummary.LastReplyAt)</span>
        </button>
    }

    @if (_hovered && ShowActions)
    {
        <div class="action-bar">
            <button class="action-btn" @onclick="OpenThread" title="Reply in thread">💬</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">😀</button>
        </div>
    }

    @if (_showEmojiPicker)
    {
        <div class="emoji-picker-anchor">
            <EmojiPicker OnEmojiSelected="HandleReaction" />
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadSummary { get; set; }
    [Parameter] public bool ShowActions { get; set; } = true;
    [Parameter] public bool IsHighlighted { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _hovered;
    private bool _showEmojiPicker;

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private void OnMouseLeave()
    {
        _hovered = false;
        _showEmojiPicker = false;
    }

    private async Task OpenThread() => await OnOpenThread.InvokeAsync(Message.Id);

    private async Task HandleReaction(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime time)
    {
        var diff = DateTime.UtcNow - time.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => time.ToString("MMM d, yyyy", CultureInfo.InvariantCulture)
        };
    }
}

.message-item {
    padding: 0.5rem 1rem;
    position: relative;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: rgba(255, 255, 255, 0.03);
}

.message-item.highlighted {
    background-color: rgba(88, 101, 242, 0.08);
    border-left: 3px solid #5865f2;
    padding-left: calc(1rem - 3px);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.author {
    font-weight: 600;
    font-size: 0.925rem;
    color: #f2f3f5;
}

.timestamp {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    color: #dcddde;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    background-color: rgba(88, 101, 242, 0.15);
    border: 1px solid rgba(88, 101, 242, 0.3);
    border-radius: 6px;
    padding: 0.125rem 0.4rem;
    font-size: 0.8rem;
    color: #dcddde;
    cursor: default;
}

.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.35rem;
    padding: 0.2rem 0;
}

.thread-link:hover {
    text-decoration: underline;
}

.thread-time {
    font-weight: 400;
    color: #72767d;
    font-size: 0.7rem;
}

.action-bar {
    position: absolute;
    top: -0.75rem;
    right: 1rem;
    display: flex;
    gap: 0.125rem;
    background-color: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.15rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 0.25rem 0.4rem;
    border-radius: 4px;
    line-height: 1;
    transition: background-color 0.1s;
}

.action-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

.emoji-picker-anchor {
    position: absolute;
    right: 1rem;
    top: -2.75rem;
    z-index: 20;
}

