@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private int _activeChannelId;
    private int _skip;
    private const int PageSize = 50;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private string ActiveChannelName =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Name ?? "";

    private string ActiveChannelDescription =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Description ?? "";

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _skip = 0;
        _threadOpen = false;
        _messages = await ChatService.GetMessagesAsync(channelId, _skip, PageSize);
        _skip = _messages.Count;
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to clear unread badge
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _skip, PageSize);
        if (older.Count == 0) return;
        _messages.InsertRange(0, older);
        _skip += older.Count;
        BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        var thread = await ChatService.GetThreadAsync(messageId);
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId)
                             ?? (thread.Count > 0 ? thread[0] : null);
        _threadReplies = thread.Where(m => m.Id != messageId).ToList();
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(
            _activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _skip > 0 ? _skip : PageSize);
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var roots = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(
                g.Key,
                g.Count(),
                g.Max(m => m.SentAt)))
            .ToList();
        _threadSummaries = roots;
    }
}

